#!/bin/sh\nset -e\nPHRASES_FILE=${PHRASES_FILE:-/phrases.txt}\nQR_OUTPUT=${QR_OUTPUT:-/qr.png}\n# Select a random phrase\nPHRASE=$(shuf -n 1 "$PHRASES_FILE")\n# Generate QR code\nqrencode -o "$QR_OUTPUT" "$PHRASE"\n# Start HTTP server serving the directory containing the QR image\nbusybox httpd -f -v -p 8080 -h "$(dirname \"$QR_OUTPUT\")" &\n# Keep container running\ntail -f /dev/null
